using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Windows.Forms;

// Assembly title and version are generated by scripts\build.ps1 from the VERSION file.

namespace Driftwall
{
    static class Program
    {
        [STAThread]
        static void Main()
        {
            // One gallery window at a time: a second launch brings the first one forward.
            bool created;
            using (var mutex = new Mutex(true, "Local\\DriftwallGallery", out created))
            {
                if (!created)
                {
                    BringExistingToFront();
                    return;
                }
                Native.SetProcessDPIAware();
                Application.EnableVisualStyles();
                Application.SetCompatibleTextRenderingDefault(false);
                Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
                Application.ThreadException += (s, e) => ReportError(e.Exception);
                AppDomain.CurrentDomain.UnhandledException += (s, e) => ReportError(e.ExceptionObject as Exception);
                Application.Run(new MainForm());
            }
        }

        static void BringExistingToFront()
        {
            var me = Process.GetCurrentProcess();
            foreach (var p in Process.GetProcessesByName(me.ProcessName))
            {
                if (p.Id != me.Id && p.MainWindowHandle != IntPtr.Zero)
                {
                    Native.ShowWindow(p.MainWindowHandle, 9 /* SW_RESTORE */);
                    Native.SetForegroundWindow(p.MainWindowHandle);
                }
                p.Dispose();
            }
        }

        // Unexpected errors are written to gallery.log next to the exe and shown once, instead of a crash dialog.
        static void ReportError(Exception e)
        {
            if (e == null) return;
            try
            {
                string log = Path.Combine(Path.GetDirectoryName(Application.ExecutablePath), "gallery.log");
                File.AppendAllText(log, DateTime.Now.ToString("s") + "  " + e + Environment.NewLine + Environment.NewLine);
            }
            catch { }
            MessageBox.Show("Something went wrong:\n\n" + e.Message + "\n\nDetails were saved to gallery.log.",
                "Driftwall", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }
}
